with st.container(key='crt_home'):
    pages=[('pages/home.py','홈'),('pages/catalog.py','오류 도감'),('pages/anatomy.py','원인 해부실'),('pages/laboratory.py','현상 실험실'),('pages/compare.py','오류 비교실')]
    cols=st.columns(5,gap='small')
    for col,(path,label) in zip(cols,pages):
        with col:
            st.page_link(path,label=label)

st.markdown('<div class="bt-featured-heading">▣ 오류 기록 미리보기 <span style="font-size:.85rem;font-weight:500">/ SELECT A FILE TO TRACE</span></div>',unsafe_allow_html=True)
st.caption('실제 컴퓨터 오류를 분석하는 12개의 기록 중 대표 사례입니다.')
for col,case_id in zip(st.columns(3,gap='medium'),[1,2,3]):
    with col:
        with st.container(key=f'featured_{case_id}'):
            case=find_case(CASES,case_id)
            if case:
                case_card(case)
                if st.button('원인 분석 열기 ↗',key=f'home_open_{case_id}',width='stretch'):
                    open_case(case_id)
